package com.tripmateai.mapper; import com.tripmateai.entity.Trip; import com.tripmateai.dto.response.trip.*; public final class TripMapper {private TripMapper(){} public static TripResponse toResponse(Trip e){if(e==null)return null; return new TripResponse(e.getId(),e.getTripName(),e.getDestination().getId(),e.getDestination().getCity(),e.getStartDate(),e.getEndDate(),e.getBudget(),e.getNumberOfTravelers(),e.getTripStatus(),e.getPreferences(),e.getCreatedAt());} public static TripSummaryResponse toSummary(Trip e){return e==null?null:new TripSummaryResponse(e.getId(),e.getTripName(),e.getDestination().getCity(),e.getStartDate(),e.getEndDate(),e.getTripStatus());}}
